                ((ScarletHunter)scarletHunterPatch.getOriginal()).setCanBypassSpeedLimit(true);
                ((ScarletHunter)scarletHunterPatch.getOriginal()).m_246865_(new Vec3(0.0, -10.0, 0.0));
